import{_ as o,o as a,c as r,a8 as t}from"./chunks/framework.D4ejoiGF.js";const f=JSON.parse('{"title":"User docs","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-chefs-embed/user-docs.md","filePath":"content/plugins/bcew-chefs-embed/user-docs.md"}'),i={name:"content/plugins/bcew-chefs-embed/user-docs.md"};function n(s,e,l,d,m,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="user-docs" tabindex="-1">User docs <a class="header-anchor" href="#user-docs" aria-label="Permalink to “User docs”">​</a></h1><p>This guide explains how site administrators can add and manage existing CHEFS forms for use in WordPress pages and posts.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to “Before you begin”">​</a></h2><p>Before configuring a form in WordPress, you will need:</p><ul><li>access to the CHEFS service</li><li>a Form ID from your form</li><li>an API key from your form</li><li>a published version of the form in CHEFS; draft-only forms cannot be embedded</li></ul><h2 id="how-to-get-your-form-id-and-api-key-for-the-chefs-plugin" tabindex="-1">How to get your Form ID and API key for the CHEFS plugin <a class="header-anchor" href="#how-to-get-your-form-id-and-api-key-for-the-chefs-plugin" aria-label="Permalink to “How to get your Form ID and API key for the CHEFS plugin”">​</a></h2><p>Log in to the CHEFS service portal at <a href="https://submit.digital.gov.bc.ca/app" target="_blank" rel="noreferrer">https://submit.digital.gov.bc.ca/app</a>.</p><h3 id="get-your-form-id" tabindex="-1">Get your Form ID <a class="header-anchor" href="#get-your-form-id" aria-label="Permalink to “Get your Form ID”">​</a></h3><ol><li>Go to <strong>My Forms</strong> and select your form.</li><li>Click <strong>Manage</strong>, then click <strong>Share form</strong> in the top right.</li><li>Copy the Form ID from the URL. For example, in <code>https://submit.digital.gov.bc.ca/app/form/submit?f=43cfb894-a0cf-4bef-8026-7c8001e3cdf5</code>, the Form ID is <code>43cfb894-a0cf-4bef-8026-7c8001e3cdf5</code>.</li></ol><p>You can also copy the Form ID from the <code>f</code> value in the URL on the form&#39;s <strong>Manage</strong> page.</p><p>Make sure the form has been published in CHEFS before adding it to WordPress. The WordPress integration requires a published version to load the form; a form that only has draft versions cannot be saved or embedded.</p><h3 id="get-your-api-key" tabindex="-1">Get your API key <a class="header-anchor" href="#get-your-api-key" aria-label="Permalink to “Get your API key”">​</a></h3><ol><li>Close the sharing popup, if it is open.</li><li>Expand the <strong>API Key</strong> accordion below the <strong>Form Settings</strong> accordion.</li><li>Click the <strong>Eye</strong> button to reveal the API key.</li><li>Click <strong>Copy</strong>.</li></ol><p>Return to WordPress Admin and enter the Form ID and API key in the new form entry.</p><h2 id="manage-forms-in-the-chefs-forms-options-page" tabindex="-1">Manage forms in the CHEFS Forms options page <a class="header-anchor" href="#manage-forms-in-the-chefs-forms-options-page" aria-label="Permalink to “Manage forms in the CHEFS Forms options page”">​</a></h2><p>Open WordPress Admin and go to CHEFS Forms.</p><h3 id="add-a-new-form" tabindex="-1">Add a new form <a class="header-anchor" href="#add-a-new-form" aria-label="Permalink to “Add a new form”">​</a></h3><ol><li>Enter a Form ID.</li><li>Enter the API Key for that form.</li><li>Click <strong>Save</strong>.</li></ol><p>CHEFS validates the Form ID and API key before WordPress saves them. If the credentials are invalid, the form is not added or updated. You may see an error when the Form ID cannot be found, the API key is invalid, or CHEFS is temporarily unavailable, or the form has no published version.</p><p>After you save:</p><ul><li>CHEFS confirms the credentials and the form title is stored in WordPress.</li><li>The form title is shown in the Configured Forms list, with the Form ID retained for support.</li><li>The form title becomes available in the CHEFS Form block options.</li></ul><p>If CHEFS cannot confirm the credentials, the form is not saved.</p><p>The Configured Forms table includes:</p><ul><li>Form ID</li><li>Form title</li><li>Date added</li><li>Confirmation message</li><li>Actions: <ul><li>Remove form</li><li>Edit confirmation</li></ul></li></ul><p>Note: API keys are hidden for security reasons.</p><h3 id="remove-a-form" tabindex="-1">Remove a form <a class="header-anchor" href="#remove-a-form" aria-label="Permalink to “Remove a form”">​</a></h3><p>Click <strong>Remove form</strong> next to the form you want to remove. A confirmation dialog asks you to confirm this cannot be undone. Choose <strong>Cancel</strong> to keep the form, or <strong>OK</strong> to remove it.</p><p>After you confirm removal:</p><ul><li>The saved Form ID and API key are removed.</li><li>The form is removed from block selection options.</li><li>The custom confirmation for that form is also removed.</li></ul><p>Note: Removing a form here does not delete the form in CHEFS. Any WordPress page embedding it will show an error until the form is saved again or the block is removed.</p><h3 id="update-an-api-key-or-change-a-form-id" tabindex="-1">Update an API key or change a Form ID <a class="header-anchor" href="#update-an-api-key-or-change-a-form-id" aria-label="Permalink to “Update an API key or change a Form ID”">​</a></h3><p>To update an API key, enter the same Form ID with the new API key and click <strong>Save</strong>. CHEFS validates the replacement credentials before WordPress updates the saved form.</p><p>Updating the API key does not change the saved form title, custom confirmation, or block embed settings. Only the credentials for that Form ID are replaced.</p><p>If validation fails, the existing saved Form ID and API key remain unchanged.</p><p>To change the Form ID, first remove the old form from the Configured Forms list, then add the new Form ID and its API key as a new form. Saving a different Form ID creates an additional configured form; it does not replace the existing row, so the old Form ID remains available in the block picker until you remove it.</p><h2 id="manage-confirmation-messages" tabindex="-1">Manage confirmation messages <a class="header-anchor" href="#manage-confirmation-messages" aria-label="Permalink to “Manage confirmation messages”">​</a></h2><ul><li>Add, edit, or remove a custom confirmation message for each configured form.</li><li>If no custom confirmation is set, a generic success message is used.</li><li>Deleting a form removes its custom confirmation.</li><li>Re-adding a form starts without a custom confirmation.</li><li>Clicking <strong>Remove custom confirmation</strong> asks for confirmation. Choose <strong>Cancel</strong> to keep the custom message, or <strong>OK</strong> to remove it and use the generic success message again.</li></ul><h2 id="add-a-chefs-form-block-to-a-page-or-post" tabindex="-1">Add a CHEFS form block to a page or post <a class="header-anchor" href="#add-a-chefs-form-block-to-a-page-or-post" aria-label="Permalink to “Add a CHEFS form block to a page or post”">​</a></h2><ol><li>Open the page or post in the block editor.</li><li>Insert the CHEFS Form block.</li><li>In the block sidebar, choose a Form ID from the dropdown.</li><li>Publish or update the page.</li></ol><h2 id="block-options" tabindex="-1">Block options <a class="header-anchor" href="#block-options" aria-label="Permalink to “Block options”">​</a></h2><ul><li><strong>Form name:</strong> Selects which saved CHEFS form to embed.</li><li>Available values come from the CHEFS Forms options page.</li><li>The Form ID remains the saved block value so the correct form is embedded.</li><li>If no forms are saved, the block shows a message and a link to open CHEFS settings.</li><li>If a selected Form ID is deleted from settings, the block selection is cleared and must be set again.</li></ul>',41)])])}const p=o(i,[["render",n]]);export{f as __pageData,p as default};
